(()=>{'use strict';const $=id=>document.getElementById(id),KEY='launchkit-v4-demo',BOOK='launchkit-v4-bookings',EVENT='launchkit-v4-events';const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const url=x=>{try{const u=new URL(x);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};const ids=['businessName','category','tagline','description','phone','whatsapp','email','instagram','snapchat','tiktok','map','primary','background','ink','bookingStart','bookingEnd'];let state={items:[],sections:['hero','items','about','booking','contact'],gallery:[],logo:'',cover:'',identityName:'',logoName:'',coverName:'',suggestion:null,step:0},sequence=0;const inp=id=>$(id).value.trim();let loading=false;const record=()=>({...state,fields:Object.fromEntries(ids.map(i=>[i,$(i).value]))});function save(){if(loading)return;try{localStorage.setItem(KEY,JSON.stringify(record()));$('notice').textContent=''}catch{$('notice').textContent='الصور كبيرة لتخزينها في المتصفح. احذف بعض الصور أو ارفع صوراً أصغر.'}}function load(){try{const val=JSON.parse(localStorage.getItem(KEY)||'null');if(!val)return;loading=true;ids.forEach(i=>{if(val.fields?.[i]!=null)$(i).value=val.fields[i]});for(const k of ['items','sections','gallery','logo','cover','identityName','logoName','coverName','suggestion'])if(val[k]!==undefined)state[k]=val[k];loading=false}catch{loading=false}}
const fileData=file=>new Promise((ok,fail)=>{if(!file.type.startsWith('image/'))return fail(Error('صيغة الملف غير مدعومة'));if(file.size>1300000)return fail(Error('الحجم الأقصى لكل صورة 1.3 ميجابايت في المعاينة المحلية'));const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=()=>fail(Error('فشلت قراءة الصورة'));r.readAsDataURL(file)});function canvas(file){return new Promise((ok,fail)=>{const img=new Image,src=URL.createObjectURL(file);img.onload=()=>{const c=document.createElement('canvas');const factor=Math.min(1,300/Math.max(img.width,img.height));c.width=Math.max(1,Math.round(img.width*factor));c.height=Math.max(1,Math.round(img.height*factor));c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(src);ok(c)};img.onerror=()=>{URL.revokeObjectURL(src);fail(Error('الصورة غير قابلة للقراءة'))};img.src=src})}const rgbhex=a=>'#'+a.map(n=>Math.max(0,Math.min(255,Math.round(n))).toString(16).padStart(2,'0')).join('');function palette(c){const px=c.getContext('2d').getImageData(0,0,c.width,c.height).data,colors=new Map();for(let i=0;i<px.length;i+=4){if(px[i+3]<90)continue;const rgb=[px[i],px[i+1],px[i+2]],key=rgb.map(n=>Math.round(n/20)*20).join(',');colors.set(key,(colors.get(key)||0)+1)}if(!colors.size)throw Error('هذه الصورة شفافة بالكامل');const ranked=[...colors].sort((a,b)=>b[1]-a[1]);let chosen=ranked.find(([k])=>{const a=k.split(',').map(Number),light=a.reduce((n,m)=>n+m,0)/3,s=Math.max(...a)-Math.min(...a);return light<235&&light>27&&s>15})||ranked.find(([k])=>{const a=k.split(',').map(Number),light=a.reduce((n,m)=>n+m,0)/3;return light<236&&light>20})||ranked[0];let r=chosen[0].split(',').map(Number);const luminance=.2126*r[0]+.7152*r[1]+.0722*r[2];return{primary:rgbhex(r),background:rgbhex(r.map(v=>Math.round(v*.09+247*.91))),ink:luminance<125?'#292729':'#27302d'}}function applyPalette(p,msg){state.suggestion=p;for(const k in p)$(k).value=p[k];$('brandStatus').textContent=msg;render()}async function analyze(file,kind){if(!file)return;let ticket=++sequence;$('brandStatus').textContent='جارٍ تحليل الألوان...';try{if(file.type==='application/pdf'){$('brandStatus').textContent='ملف PDF محفوظ كاسم فقط حالياً؛ للحصول على ألوانه ارفع صورة من دليل الهوية. لم نطبّق ألواناً غير مؤكدة.';return}const p=palette(await canvas(file));if(ticket!==sequence)return;if(kind==='logo'&&state.identityName){$('brandStatus').textContent='تم تغيير الشعار؛ ألوان ملف الهوية لها الأولوية. لإعادة تحليل الشعار احذف ملف الهوية.';return}applyPalette(p,kind==='logo'?'تم استخلاص ألوان الشعار وتطبيقها تلقائياً.':'تم تطبيق ألوان ملف الهوية المصور.')}catch(e){$('brandStatus').textContent=e.message}}
function info(){for(const kind of ['logo','cover','identity']){$(kind+'Chosen').textContent=kind==='logo'?state.logoName:kind==='cover'?state.coverName:state.identityName;$('remove'+kind[0].toUpperCase()+kind.slice(1)).hidden=!((kind==='logo'&&state.logo)||(kind==='cover'&&state.cover)||(kind==='identity'&&state.identityName))}const map=url(inp('map'));$('mapPreview').hidden=!map;if(map)$('mapPreview').href=map;$('mapStatus').textContent=map?'معاينة الرابط جاهزة: اضغط لفتح الموقع على خرائط Google':inp('map')?'الرابط غير صالح؛ استخدم رابط https:// من خرائط Google':'';const root=$('galleryThumbs');root.replaceChildren();state.gallery.forEach((src,i)=>{const wrap=document.createElement('div');wrap.className='thumb';const img=document.createElement('img');img.src=src;img.alt='صورة المعرض '+(i+1);const b=document.createElement('button');b.textContent='حذف الصورة ×';b.onclick=()=>{state.gallery.splice(i,1);render()};wrap.append(img,b);root.append(wrap)})}
function listItems(){$('itemsList').replaceChildren();state.items.forEach((it,i)=>{const row=document.createElement('div');row.className='item-row';const txt=document.createElement('span');txt.textContent=`${it.name} · ${it.price||'0'} ر.س · ${it.description||'بدون وصف'}`;const del=document.createElement('button');del.textContent='حذف';del.onclick=()=>{state.items.splice(i,1);render()};row.append(txt,del);$('itemsList').append(row)})}const sectionLabels={hero:'واجهة رئيسية',items:'المنتجات والخدمات',gallery:'معرض الصور',about:'من نحن',contact:'تواصل معنا',booking:'المواعيد',inquiry:'الاستفسارات',map:'موقعنا'};function listSections(){$('sectionsList').replaceChildren();state.sections.forEach((kind,i)=>{const r=document.createElement('div');r.className='section-row';const txt=document.createElement('span');txt.textContent=sectionLabels[kind];const group=document.createElement('div');for(const [word,dir] of [['↑',-1],['↓',1]]){const b=document.createElement('button');b.textContent=word;b.disabled=i+dir<0||i+dir>=state.sections.length;b.onclick=()=>{[state.sections[i],state.sections[i+dir]]=[state.sections[i+dir],state.sections[i]];render()};group.append(b)}const del=document.createElement('button');del.textContent='حذف';del.onclick=()=>{state.sections.splice(i,1);render()};group.append(del);r.append(txt,group);$('sectionsList').append(r)})}function preview(){const frame=$('liveFrame');const snapshot=JSON.stringify(record());frame.contentWindow?.postMessage({type:'LAUNCHKIT_STATE',data:snapshot},'*');if(!frame.dataset.loaded){frame.src='site.html?preview=1';frame.dataset.loaded='1'}}function render(){info();listItems();listSections();save();preview()}
function step(n){state.step=Math.max(0,Math.min(4,n));document.querySelectorAll('[data-pane]').forEach(e=>e.classList.toggle('active',Number(e.dataset.pane)===state.step));document.querySelectorAll('.step').forEach(e=>e.classList.toggle('active',Number(e.dataset.step)===state.step));$('prev').disabled=state.step===0;$('next').textContent=state.step===4?'تجهيز الموقع':'التالي'}function show(where){$('builder').hidden=where!=='builder';$('owner').hidden=where!=='owner';$('platform').hidden=where!=='platform';if(where==='owner')dashboard();if(where==='platform')platform();window.scrollTo(0,0)}const bookings=()=>JSON.parse(localStorage.getItem(BOOK)||'[]');const events=()=>JSON.parse(localStorage.getItem(EVENT)||'[]');function dashboard(tab='overview'){const nav=$('ownerNav');nav.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const entries=bookings(),evs=events(),r=$('ownerContent');const stats=`<div class="dash-cards"><div class="dash-card"><small>مشاهدات محلية مسجلة</small><strong>${evs.filter(e=>e.type==='view').length}</strong><small>تجربة محلية فقط</small></div><div class="dash-card"><small>نقرات التواصل</small><strong>${evs.filter(e=>e.type==='contact').length}</strong></div><div class="dash-card"><small>طلبات المواعيد</small><strong>${entries.length}</strong></div><div class="dash-card"><small>العملاء المسجلون</small><strong>—</strong><small>يتطلب حسابات فعلية</small></div></div>`;if(tab==='overview'){r.innerHTML=stats+`<div class="dash-panel"><h2>آخر الحجوزات</h2>${entries.slice(-4).map(e=>`<p>${safe(e.name)} — ${safe(e.service)} — ${safe(e.date)} ${safe(e.time)} — ${safe(e.status)}</p>`).join('')||'<p>لا توجد حجوزات حتى الآن.</p>'}</div>`}else if(tab==='bookings'){r.innerHTML=`<div class="dash-panel"><h2>إدارة المواعيد</h2><table class="data-table"><thead><tr><th>العميل</th><th>الخدمة</th><th>التاريخ</th><th>الوقت</th><th>الحالة</th><th>تحديث</th></tr></thead><tbody>${entries.map(e=>`<tr><td>${safe(e.name)}</td><td>${safe(e.service)}</td><td>${safe(e.date)}</td><td>${safe(e.time)}</td><td>${safe(e.status)}</td><td><button data-book="${safe(e.id)}" data-status="confirmed">تأكيد</button> <button data-book="${safe(e.id)}" data-status="cancelled">إلغاء</button></td></tr>`).join('')}</tbody></table>${entries.length?'':'<p>لا توجد حجوزات.</p>'}</div>`;r.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>{const x=bookings(),e=x.find(a=>a.id===b.dataset.book);if(e){e.status=b.dataset.status;localStorage.setItem(BOOK,JSON.stringify(x));dashboard('bookings')}})}else if(tab==='customers'){r.innerHTML='<div class="dash-panel"><h2>العملاء</h2><p>أسماء أصحاب الحجوزات موجودة في قسم المواعيد؛ نظام حسابات العملاء وتسجيل الدخول سيُربط لاحقاً بـ PHP/MySQL.</p></div>'}else if(tab==='products'){r.innerHTML=`<div class="dash-panel"><h2>الخدمات والمنتجات</h2>${state.items.map(i=>`<p><b>${safe(i.name)}</b> — ${safe(i.description)} — ${safe(i.price)} ر.س</p>`).join('')||'<p>لا توجد منتجات.</p>'}<button id="goItems" class="secondary">تعديل الخدمات</button></div>`;$('goItems').onclick=()=>{show('builder');step(3)}}else if(tab==='analytics'){r.innerHTML=stats+'<div class="dash-panel"><h2>حول التحليلات</h2><p>هذه قياسات للمتصفح المحلي ولا تمثل زيارات مستخدمين حقيقيين أو زواراً فريدين. نحتاج خادماً وطرق ضبط للخصوصية والتصفية قبل الاعتماد عليها.</p></div>'}else{r.innerHTML='<div class="dash-panel"><h2>إدارة الموقع</h2><p>يمكنك تعديل الهوية والصفحات والمحتوى في المحرر.</p><button id="editSite" class="secondary">فتح المحرر</button> <button id="visitSite" class="quiet">زيارة الموقع</button></div>';$('editSite').onclick=()=>show('builder');$('visitSite').onclick=openSite}}
function platform(){$('platformContent').innerHTML='<div class="dash-cards"><div class="dash-card"><small>الحسابات الحقيقية</small><strong>—</strong></div><div class="dash-card"><small>المواقع المنشورة للعامة</small><strong>—</strong></div><div class="dash-card"><small>بلاغات ومشكلات</small><strong>—</strong></div><div class="dash-card"><small>حالة الخوادم</small><strong>—</strong></div></div><div class="dash-panel"><h2>العمليات المطلوبة للمنصة</h2><p>إدارة المستخدمين والمواقع، صلاحيات المشرف، إيقاف المواقع المخالفة، السجلات، التخزين، الحدود، الدعم، النسخ الاحتياطية، التحليلات والأمان. هذه لوحة متطلبات وليست لوحة إدارة إنتاجية.</p></div>'}function openSite(){save();window.open('site.html','_blank','noopener,noreferrer')}function publish(){save();$('siteLink').textContent=new URL('site.html',location.href).href;$('publishDialog').showModal()}
load();$('liveFrame').addEventListener('load',preview);document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>step(Number(b.dataset.step)));document.querySelectorAll('[data-device]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.device').forEach(x=>x.classList.toggle('active',x===b));$('frameHolder').className='frameHolder '+b.dataset.device;$('deviceName').textContent={desktop:'سطح المكتب',tablet:'تابلت',phone:'جوال'}[b.dataset.device]});ids.forEach(id=>$(id).addEventListener(id==='category'?'change':'input',()=>{if(id==='category'){$('durationField').hidden=['store','food'].includes(inp('category'));$('itemsHeading').textContent=['store','food'].includes(inp('category'))?'المنتجات وأسعارها':'الخدمات وأسعارها';state.sections=inp('category')==='booking'?['hero','items','gallery','booking','contact']:['hero','items','gallery','about','contact']}render()}));$('prev').onclick=()=>step(state.step-1);$('next').onclick=()=>state.step===4?publish():step(state.step+1);$('buildBtn').onclick=publish;$('closeDialog').onclick=()=>$('publishDialog').close();$('openPublished').onclick=openSite;$('previewBtn').onclick=openSite;$('ownerBtn').onclick=()=>show('owner');$('platformBtn').onclick=()=>show('platform');$('backBuilder').onclick=$('backPlatform').onclick=()=>show('builder');$('ownerNav').querySelectorAll('button').forEach(b=>b.onclick=()=>dashboard(b.dataset.tab));$('addItem').onclick=()=>{if(!inp('itemName'))return $('notice').textContent='أدخل اسم العنصر';if(inp('itemLink')&&!url(inp('itemLink')))return $('notice').textContent='رابط المنتج غير صالح';state.items.push({name:inp('itemName'),description:inp('itemDescription'),price:inp('itemPrice'),duration:Number(inp('itemDuration'))||60,link:inp('itemLink')});for(const k of ['itemName','itemDescription','itemPrice','itemLink'])$(k).value='';render()};$('addSection').onclick=()=>{state.sections.push(inp('sectionType'));render()};$('resetPalette').onclick=()=>{if(state.suggestion)applyPalette(state.suggestion,'تم استعادة الألوان المقترحة')};$('logo').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{state.logo=await fileData(f);state.logoName=f.name;render();await analyze(f,'logo')}catch(ex){$('brandStatus').textContent=ex.message}};$('identity').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;state.identityName=f.name;render();await analyze(f,'identity')};$('cover').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{state.cover=await fileData(f);state.coverName=f.name;render()}catch(ex){$('notice').textContent=ex.message}};$('gallery').onchange=async e=>{const f=[...e.target.files];if(!f.length)return;try{state.gallery=[...state.gallery,...await Promise.all(f.map(fileData))].slice(0,6);if(!state.sections.includes('gallery'))state.sections.push('gallery');render()}catch(ex){$('notice').textContent=ex.message}};$('removeLogo').onclick=()=>{state.logo='';state.logoName='';$('logo').value='';sequence++;render()};$('removeIdentity').onclick=()=>{state.identityName='';$('identity').value='';sequence++;$('brandStatus').textContent='أُزيل ملف الهوية. لإعادة اقتراح ألوان الشعار ارفعه مجدداً أو استعد الألوان المقترحة.';render()};$('removeCover').onclick=()=>{state.cover='';state.coverName='';$('cover').value='';render()};render();step(0);})();
